-- Generated by scripts/build-ai-work-records-catalog.ts.
-- Apply core first, deploy ask-bob AND bob-worker, then activate this publication.
begin;
do $server_bound_edits_catalog$
declare contracts jsonb:=$bound_edit_contracts$[
  {
    "name": "read_work_context",
    "description": "Read complete server-bound work records. Choose a returned ref; never copy database identities or versions. Resources include archived Areas and measurements for explicit restore. next_ref continues the same filter. People and current Plan Steps are relation choices. A read is metadata, never proof of inspection or completed work.",
    "parameters": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "resource": {
          "type": "string",
          "enum": [
            "project",
            "areas",
            "tasks",
            "measurements",
            "build_days",
            "people",
            "plan_steps",
            "components",
            "shopping"
          ]
        },
        "query": {
          "type": [
            "string",
            "null"
          ]
        },
        "next_ref": {
          "type": [
            "string",
            "null"
          ]
        }
      },
      "required": [
        "resource",
        "query",
        "next_ref"
      ]
    }
  },
  {
    "name": "edit_work_record",
    "description": "Edit only the requested content fields on a ref from read_work_context. Paths: Areas /name /description; Tasks /name /instructions; measurements /subject /value /unit /truth /source /notes /required; build_days /title /day /time /place /food; project /start_date /end_date (both null to clear). Operations set or append_text only. Other values, scope, assignments, scheduled Tasks and image evidence are preserved automatically. Unknown remains unknown; never call an inferred size measured. Read again after saving.",
    "parameters": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "ref": {
          "type": "string"
        },
        "changes": {
          "type": "array",
          "minItems": 1,
          "maxItems": 40,
          "items": {
            "type": "object",
            "additionalProperties": false,
            "properties": {
              "op": {
                "type": "string",
                "enum": [
                  "set",
                  "append_text",
                  "remove"
                ]
              },
              "path": {
                "type": "string"
              },
              "value_json": {
                "type": [
                  "string",
                  "null"
                ],
                "description": "JSON-encoded new value. null only for remove. append_text appends the decoded string verbatim."
              }
            },
            "required": [
              "op",
              "path",
              "value_json"
            ]
          }
        },
        "reason": {
          "type": "string"
        },
        "request_quote": {
          "type": "string"
        }
      },
      "required": [
        "ref",
        "changes",
        "reason",
        "request_quote"
      ]
    }
  },
  {
    "name": "create_work_record",
    "description": "Explicitly create a new Area, Task, measurement or build day. Read existing records first; never create to repair a rejected edit. scope_ref chooses project for Areas/build days, an Area or current Plan Step for Tasks, project/Area/component for measurements. base_ref optionally copies an existing record of the same resource and its existing content or scheduled task list; provide only differences. With no base use content paths from edit_work_record. New measurements default to unknown until actual evidence is supplied. New Tasks start todo without assignments; copying content does not certify work.",
    "parameters": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "resource": {
          "type": "string",
          "enum": [
            "areas",
            "tasks",
            "measurements",
            "build_days"
          ]
        },
        "scope_ref": {
          "type": "string"
        },
        "base_ref": {
          "type": [
            "string",
            "null"
          ]
        },
        "changes": {
          "type": "array",
          "minItems": 1,
          "maxItems": 40,
          "items": {
            "type": "object",
            "additionalProperties": false,
            "properties": {
              "op": {
                "type": "string",
                "enum": [
                  "set",
                  "append_text",
                  "remove"
                ]
              },
              "path": {
                "type": "string"
              },
              "value_json": {
                "type": [
                  "string",
                  "null"
                ],
                "description": "JSON-encoded new value. null only for remove. append_text appends the decoded string verbatim."
              }
            },
            "required": [
              "op",
              "path",
              "value_json"
            ]
          }
        },
        "reason": {
          "type": "string"
        },
        "request_quote": {
          "type": "string"
        }
      },
      "required": [
        "resource",
        "scope_ref",
        "base_ref",
        "changes",
        "reason",
        "request_quote"
      ]
    }
  },
  {
    "name": "change_work_relation",
    "description": "Add or remove one person assignment on a Task, or one scheduled Task on a build day. target_ref and source_ref come from read_work_context. All other members are preserved. This does not change RSVP, readiness or completion.",
    "parameters": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "target_ref": {
          "type": "string"
        },
        "source_ref": {
          "type": "string"
        },
        "action": {
          "type": "string",
          "enum": [
            "add",
            "remove"
          ]
        },
        "reason": {
          "type": "string"
        },
        "request_quote": {
          "type": "string"
        }
      },
      "required": [
        "target_ref",
        "source_ref",
        "action",
        "reason",
        "request_quote"
      ]
    }
  },
  {
    "name": "change_work_state",
    "description": "Explicit work state change on a ref from read_work_context. action archive/restore applies to Areas or measurements (value=null); delete to unfinished Tasks, build days or Shopping rows (value=null); status to Tasks (value=todo|doing|done|blocked); phase to project/Area (value=concept|design|planning|build|complete). Preserve all other data. Completed Tasks are retained; canonical readiness/phase rules still apply. A requested state is not invented physical evidence.",
    "parameters": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "ref": {
          "type": "string"
        },
        "action": {
          "type": "string",
          "enum": [
            "archive",
            "restore",
            "delete",
            "status",
            "phase"
          ]
        },
        "value": {
          "type": [
            "string",
            "null"
          ]
        },
        "reason": {
          "type": "string"
        },
        "request_quote": {
          "type": "string"
        }
      },
      "required": [
        "ref",
        "action",
        "value",
        "reason",
        "request_quote"
      ]
    }
  }
]$bound_edit_contracts$::jsonb;
 policies jsonb:=$bound_edit_policies$[
  {
    "name": "read_work_context",
    "description": "Read server-bound work records and relation choices.",
    "how_to": "Read the relevant work records first. Reuse returned refs; provide only intended deltas. Never transcribe IDs, versions, scope or unchanged values. Creation cannot repair a failed edit. Unknown stays unknown; canonical domain rules remain authoritative.",
    "schema_version": 1,
    "always_load": false,
    "preload_phases": [
      "concept",
      "design",
      "planning",
      "build",
      "complete"
    ],
    "active": true
  },
  {
    "name": "edit_work_record",
    "description": "Change only requested content on an existing work record.",
    "how_to": "Read the relevant work records first. Reuse returned refs; provide only intended deltas. Never transcribe IDs, versions, scope or unchanged values. Creation cannot repair a failed edit. Unknown stays unknown; canonical domain rules remain authoritative.",
    "schema_version": 1,
    "always_load": false,
    "preload_phases": [
      "concept",
      "design",
      "planning",
      "build",
      "complete"
    ],
    "active": true
  },
  {
    "name": "create_work_record",
    "description": "Explicitly create new work from a read scope and optional base.",
    "how_to": "Read the relevant work records first. Reuse returned refs; provide only intended deltas. Never transcribe IDs, versions, scope or unchanged values. Creation cannot repair a failed edit. Unknown stays unknown; canonical domain rules remain authoritative.",
    "schema_version": 1,
    "always_load": false,
    "preload_phases": [
      "concept",
      "design",
      "planning",
      "build",
      "complete"
    ],
    "active": true
  },
  {
    "name": "change_work_relation",
    "description": "Add or remove one assignment or scheduled Task.",
    "how_to": "Read the relevant work records first. Reuse returned refs; provide only intended deltas. Never transcribe IDs, versions, scope or unchanged values. Creation cannot repair a failed edit. Unknown stays unknown; canonical domain rules remain authoritative.",
    "schema_version": 1,
    "always_load": false,
    "preload_phases": [
      "concept",
      "design",
      "planning",
      "build",
      "complete"
    ],
    "active": true
  },
  {
    "name": "change_work_state",
    "description": "Change lifecycle or Task status on an exact read record.",
    "how_to": "Read the relevant work records first. Reuse returned refs; provide only intended deltas. Never transcribe IDs, versions, scope or unchanged values. Creation cannot repair a failed edit. Unknown stays unknown; canonical domain rules remain authoritative.",
    "schema_version": 1,
    "always_load": false,
    "preload_phases": [
      "concept",
      "design",
      "planning",
      "build",
      "complete"
    ],
    "active": true
  }
]$bound_edit_policies$::jsonb;
 append jsonb:=$bound_edit_append$[
  {
    "key": "tools.save_project_area",
    "text": " Superseded for fresh manifests by read_work_context and explicit edit_work_record/create_work_record/change_work_relation/change_work_state. Runtime binds identity, exact snapshot, scope and preserved data."
  },
  {
    "key": "tools.save_project_task",
    "text": " Superseded for fresh manifests by read_work_context and explicit edit_work_record/create_work_record/change_work_relation/change_work_state. Runtime binds identity, exact snapshot, scope and preserved data."
  },
  {
    "key": "tools.save_project_measurement",
    "text": " Superseded for fresh manifests by read_work_context and explicit edit_work_record/create_work_record/change_work_relation/change_work_state. Runtime binds identity, exact snapshot, scope and preserved data."
  },
  {
    "key": "tools.archive_project_measurement",
    "text": " Superseded for fresh manifests by read_work_context and explicit edit_work_record/create_work_record/change_work_relation/change_work_state. Runtime binds identity, exact snapshot, scope and preserved data."
  },
  {
    "key": "tools.update_project_task_work",
    "text": " Superseded for fresh manifests by read_work_context and explicit edit_work_record/create_work_record/change_work_relation/change_work_state. Runtime binds identity, exact snapshot, scope and preserved data."
  },
  {
    "key": "tools.save_project_build_day",
    "text": " Superseded for fresh manifests by read_work_context and explicit edit_work_record/create_work_record/change_work_relation/change_work_state. Runtime binds identity, exact snapshot, scope and preserved data."
  },
  {
    "key": "tools.delete_project_task",
    "text": " Superseded for fresh manifests by read_work_context and explicit edit_work_record/create_work_record/change_work_relation/change_work_state. Runtime binds identity, exact snapshot, scope and preserved data."
  },
  {
    "key": "tools.delete_project_build_day",
    "text": " Superseded for fresh manifests by read_work_context and explicit edit_work_record/create_work_record/change_work_relation/change_work_state. Runtime binds identity, exact snapshot, scope and preserved data."
  },
  {
    "key": "tools.archive_project_area",
    "text": " Superseded for fresh manifests by read_work_context and explicit edit_work_record/create_work_record/change_work_relation/change_work_state. Runtime binds identity, exact snapshot, scope and preserved data."
  },
  {
    "key": "tools.set_project_phase",
    "text": " Superseded for fresh manifests by read_work_context and explicit edit_work_record/create_work_record/change_work_relation/change_work_state. Runtime binds identity, exact snapshot, scope and preserved data."
  },
  {
    "key": "tools.update_project_schedule",
    "text": " Superseded for fresh manifests by read_work_context and explicit edit_work_record/create_work_record/change_work_relation/change_work_state. Runtime binds identity, exact snapshot, scope and preserved data."
  },
  {
    "key": "tools.delete_shopping_item",
    "text": " Superseded for fresh manifests by read_work_context and explicit edit_work_record/create_work_record/change_work_relation/change_work_state. Runtime binds identity, exact snapshot, scope and preserved data."
  }
]$bound_edit_append$::jsonb;
 patch jsonb; policy jsonb; prior shared.ai_prompt_versions; template shared.ai_prompt_versions;
 prompt_uuid uuid; version_uuid uuid; next_version integer; definition jsonb; activation jsonb:='{}';
begin
 perform pg_advisory_xact_lock(hashtextextended('ai_catalog:bob',0));
 select v.* into template from shared.ai_prompts p join shared.ai_prompt_versions v on v.id=p.active_version_id where p.app='bob' and p.prompt_key='tools.save_project_description';
 if not found then raise exception 'bound_edit_template_missing'; end if;
 for patch in select value from jsonb_array_elements(contracts) loop
  select value into policy from jsonb_array_elements(policies) where value->>'name'=patch->>'name';
  select v.* into prior from shared.ai_prompts p join shared.ai_prompt_versions v on v.id=p.active_version_id where p.app='bob' and p.prompt_key='tools.'||(patch->>'name');
  if not found then
   insert into shared.ai_prompts(app,prompt_key,label,description,content,flow,definition_kind)
    values('bob','tools.'||(patch->>'name'),policy->>'description',policy->>'description','','','tool_contract') returning id into prompt_uuid;
   prior:=template;
  else prompt_uuid:=prior.prompt_id;
  end if;
  definition:=prior.definition||patch||jsonb_build_object('handler',patch->>'name','required_parameters',patch#>'{parameters,required}','optional_parameters','[]'::jsonb,'additional_description',policy->>'how_to');
  definition:=jsonb_set(definition,'{envelope,schema_version}','1'::jsonb);
  select coalesce(max(version),0)+1 into next_version from shared.ai_prompt_versions where prompt_id=prompt_uuid;
  insert into shared.ai_prompt_versions(prompt_id,version,definition_kind,definition_format_version,metadata,content,definition,flow,available_variables)
   values(prompt_uuid,next_version,'tool_contract',1,jsonb_build_object('publication','server-bound-work-records','server_fields',case when patch->>'name'<>'read_work_context' then ' ["request_quote"]'::jsonb else '[]'::jsonb end),prior.content,definition,prior.flow,prior.available_variables) returning id into version_uuid;
  activation:=activation||jsonb_build_object('tools.'||(patch->>'name'),version_uuid);
 end loop;
 for patch in select value from jsonb_array_elements(append) loop
  select v.* into prior from shared.ai_prompts p join shared.ai_prompt_versions v on v.id=p.active_version_id where p.app='bob' and p.prompt_key=patch->>'key';
  if not found then raise exception 'bound_edit_legacy_contract_missing'; end if;
  definition:=jsonb_set(prior.definition,'{additional_description}',to_jsonb(coalesce(prior.definition->>'additional_description','')||(patch->>'text')));
  select coalesce(max(version),0)+1 into next_version from shared.ai_prompt_versions where prompt_id=prior.prompt_id;
  insert into shared.ai_prompt_versions(prompt_id,version,definition_kind,definition_format_version,metadata,content,definition,flow,available_variables)
   values(prior.prompt_id,next_version,prior.definition_kind,prior.definition_format_version,(prior.metadata-'seed_version'-'source_revision')||jsonb_build_object('publication','server-bound-work-records'),prior.content,definition,prior.flow,prior.available_variables) returning id into version_uuid;
  activation:=activation||jsonb_build_object(patch->>'key',version_uuid);
 end loop;
 select v.* into prior from shared.ai_prompts p join shared.ai_prompt_versions v on v.id=p.active_version_id where p.app='bob' and p.prompt_key='bob.tools' for update of p;
 if not found then raise exception 'bound_edit_toolbox_missing'; end if;
 definition:=prior.definition;
 for policy in select value from jsonb_array_elements(policies) loop
  insert into bob.tool_catalog(name,description,how_to,schema_version,always_load,preload_phases,active)
   values(policy->>'name',policy->>'description',policy->>'how_to',(policy->>'schema_version')::integer,(policy->>'always_load')::boolean,array(select jsonb_array_elements_text(policy->'preload_phases')),(policy->>'active')::boolean)
   on conflict(name) do nothing;
  if not exists(select 1 from jsonb_array_elements(definition->'catalog') r where r->>'name'=policy->>'name') then
   definition:=jsonb_set(definition,'{catalog}',definition->'catalog'||jsonb_build_array(policy));
  end if;
  if not definition->'contract_keys'?('tools.'||(policy->>'name')) then
   definition:=jsonb_set(definition,'{contract_keys}',definition->'contract_keys'||jsonb_build_array('tools.'||(policy->>'name')));
  end if;
  definition:=jsonb_set(definition,'{shelves}',(select jsonb_agg(case when shelf->>'label'='Project records and memory' and not shelf->'tools'?(policy->>'name') then jsonb_set(shelf,'{tools}',shelf->'tools'||jsonb_build_array(policy->>'name')) else shelf end) from jsonb_array_elements(definition->'shelves') shelf));
 end loop;
 select coalesce(max(version),0)+1 into next_version from shared.ai_prompt_versions where prompt_id=prior.prompt_id;
 insert into shared.ai_prompt_versions(prompt_id,version,definition_kind,definition_format_version,metadata,content,definition,flow,available_variables)
  values(prior.prompt_id,next_version,prior.definition_kind,prior.definition_format_version,(prior.metadata-'seed_version'-'source_revision')||jsonb_build_object('publication','server-bound-work-records'),prior.content,definition,prior.flow,prior.available_variables) returning id into version_uuid;
 activation:=activation||jsonb_build_object('bob.tools',version_uuid);
 perform shared.activate_ai_catalog('bob',activation);
end $server_bound_edits_catalog$;
commit;
